const series = context.panel.data.series[0];

const rollField = series.fields.find(
  f => f.name === "roll_deg"
);

const pitchField = series.fields.find(
  f => f.name === "pitch_deg"
);

const roll = Number(
  rollField?.values.get(
    rollField.values.length - 1
  ) ?? 0
);

const pitch = Number(
  pitchField?.values.get(
    pitchField.values.length - 1
  ) ?? 0
);

const rollRad =
  roll * Math.PI / 180;

const pitchRad =
  pitch * Math.PI / 180;

// ----------------------------------
// Bridge deck
// ----------------------------------

const deck = [];

for (let x = -40; x <= 40; x += 0.5) {

  for (let y = -4; y <= 4; y += 0.25) {

    const z =
      x * Math.sin(pitchRad) +
      y * Math.sin(rollRad);

    deck.push([
      x,
      y,
      z
    ]);
  }
}

// ----------------------------------
// Left support
// ----------------------------------

const leftSupport = [];

for (let z = -15; z <= 0; z += 0.5) {

  for (let y = -3; y <= 3; y += 0.5) {

    leftSupport.push([
      -35,
      y,
      z
    ]);
  }
}

// ----------------------------------
// Right support
// ----------------------------------

const rightSupport = [];

for (let z = -15; z <= 0; z += 0.5) {

  for (let y = -3; y <= 3; y += 0.5) {

    rightSupport.push([
      35,
      y,
      z
    ]);
  }
}

// ----------------------------------
// Main beam under deck
// ----------------------------------

const beam = [];

for (let x = -35; x <= 35; x += 0.5) {

  beam.push([
    x,
    0,
    -2
  ]);
}

// ----------------------------------
// Chart
// ----------------------------------

return {

  title: {
    text:
      `Bridge | Roll ${roll.toFixed(1)}° | ` +
      `Pitch ${pitch.toFixed(1)}°`
  },

  tooltip: {},

  xAxis3D: {
    name: 'Length [cm]',
    min: -45,
    max: 45
  },

  yAxis3D: {
    name: 'Width [cm]',
    min: -6,
    max: 6
  },

  zAxis3D: {
    name: 'Height',
    min: -20,
    max: 10
  },

  grid3D: {

    boxWidth: 180,
    boxDepth: 30,
    boxHeight: 60,

    viewControl: {

      projection: 'perspective',

      alpha: 20,
      beta: 35,

      distance: 120,

      rotateSensitivity: 5,
      zoomSensitivity: 5,
      panSensitivity: 2
    }
  },

  series: [

    // Deck
    {
      type: 'scatter3D',

      symbol: 'square',

      symbolSize: 6,

      data: deck
    },

    // Left support
    {
      type: 'scatter3D',

      symbol: 'square',

      symbolSize: 5,

      data: leftSupport
    },

    // Right support
    {
      type: 'scatter3D',

      symbol: 'square',

      symbolSize: 5,

      data: rightSupport
    },

    // Main beam
    {
      type: 'scatter3D',

      symbol: 'square',

      symbolSize: 8,

      data: beam
    }
  ]
};
